select
  'nutrition-research-methods',
  null,
  'Nutrition Research Methods',
  'Nutrition Research Methods',
  'This advanced undergraduate course develops the ability to ask, design, appraise, analyze, reproduce, and communicate nutrition research. Students progress from a consequential research question to a feasible protocol, integrating literature searching, causal and conceptual models, experimental and observational designs, dietary and nutrition-status measurement, qualitative and mixed methods, sampling, biostatistics, bias analysis, research ethics, open science, critical appraisal, evidence synthesis, scientific reporting, and knowledge translation. Applied laboratories use public or simulated nutrition data and culminate in a preregistered-style research proposal, reproducible analytic product, and oral defense.',
  $nrmjson${"slug": "nutrition-research-methods", "title": "Nutrition Research Methods", "description": "This advanced undergraduate course develops the ability to ask, design, appraise, analyze, reproduce, and communicate nutrition research. Students progress from a consequential research question to a feasible protocol, integrating literature searching, causal and conceptual models, experimental and observational designs, dietary and nutrition-status measurement, qualitative and mixed methods, sampling, biostatistics, bias analysis, research ethics, open science, critical appraisal, evidence synthesis, scientific reporting, and knowledge translation. Applied laboratories use public or simulated nutrition data and culminate in a preregistered-style research proposal, reproducible analytic product, and oral defense.", "topics": [{"id": "a65a0f63-cf65-4662-9aaa-501f02a0a1e1", "type": "topic", "title": "Research Foundations, Questions, and Protocol Logic", "description": "This section turns broad nutrition interests into answerable, ethical studies. Students learn that a coherent protocol begins with a consequential question and maintains alignment among the population, exposure or intervention, comparison, outcomes, timing, design, and analysis.", "children": [{"id": "c40a7827-2e19-4482-b2e3-956580b950be", "type": "subtopic", "title": "From problem to research question", "description": "The point is to define a question precise enough to guide evidence searching, measurement, and design while remaining meaningful to nutrition practice or population health.", "children": [{"id": "cdaa0e78-b696-4137-9b20-6e090f626ecd", "type": "concept", "title": "Problem statements, knowledge gaps, significance, and stakeholder relevance"}, {"id": "71afe6b3-9c8d-418f-ad49-a4d3acb330ef", "type": "concept", "title": "PICO, PECO, PICOT, SPIDER, and question frameworks for quantitative and qualitative inquiry"}, {"id": "15518b02-4536-438d-a94c-5be5f1488dc1", "type": "concept", "title": "Primary and secondary questions; explanatory, descriptive, predictive, and evaluative aims"}]}, {"id": "ec69f1f9-814e-4b11-a909-013691a0d701", "type": "subtopic", "title": "Conceptual models and hypotheses", "description": "A conceptual model makes assumptions visible before variables are collected or models are fitted.", "children": [{"id": "0ed45cc9-02d7-4f52-97e8-bf58d63226c3", "type": "concept", "title": "Constructs, variables, mechanisms, causal pathways, and theory"}, {"id": "1a659b10-04af-4a5a-b288-05aab27981b4", "type": "concept", "title": "Directional hypotheses, null hypotheses, estimands, and falsifiability"}, {"id": "c118df01-6735-4d4b-afa2-fcfff034cb5a", "type": "concept", "title": "Logic models, causal diagrams, mediators, confounders, colliders, and effect modifiers"}]}, {"id": "b60c4a45-8862-4a53-958c-9a9320a6f7e6", "type": "subtopic", "title": "Protocol coherence and feasibility", "description": "Students learn to test whether a proposed study can actually answer its question with available time, participants, measures, expertise, and resources.", "children": [{"id": "e40a53f6-ab39-457c-ba86-bb65e2044930", "type": "concept", "title": "Alignment of aims, design, measures, sampling, analysis, and interpretation"}, {"id": "1951e1ff-d614-4abc-a0c7-c2fb9d798e32", "type": "concept", "title": "Feasibility, acceptability, burden, cost, timeline, staffing, and pilot work"}, {"id": "62e8bd7f-177b-4a78-bc25-58791cfd455b", "type": "concept", "title": "Protocol version control, deviations, amendments, decision logs, and stopping rules"}]}]}, {"id": "e123f90f-9bc3-4caf-967a-11a9bc0181f5", "type": "topic", "title": "Literature Searching and Evidence Landscapes", "description": "Research begins by locating what is known, how it was studied, and where uncertainty remains. Students build transparent searches and organize evidence without confusing search-engine visibility with scientific quality.", "children": [{"id": "8b6e3cb2-196b-4ef2-9e05-5b6682c8c08c", "type": "subtopic", "title": "Information sources and search strategy", "description": "Students learn to choose databases and construct reproducible searches for nutrition, biomedical, behavioral, and public-health questions.", "children": [{"id": "8d0ce285-f011-4f73-8e9a-1780285b5bd0", "type": "concept", "title": "PubMed/MEDLINE, Embase, CINAHL, PsycINFO, Cochrane Library, Scopus/Web of Science, and grey literature"}, {"id": "7be7fd41-c6d6-4c59-926f-9a9e8cb9e30b", "type": "concept", "title": "Controlled vocabulary, keywords, Boolean logic, proximity, truncation, filters, and citation chaining"}, {"id": "77529210-cef9-4331-a54b-f66a25844e0d", "type": "concept", "title": "Search dates, full search strings, deduplication, alerts, and librarian consultation"}]}, {"id": "4b2062be-fbb5-4dec-9ed2-9215628f2d2a", "type": "subtopic", "title": "Screening, organization, and citation management", "description": "The goal is an auditable path from search results to the evidence used in a proposal or review.", "children": [{"id": "4fe8b031-4e3a-43b5-978b-28b1f59850c5", "type": "concept", "title": "Eligibility criteria, title/abstract screening, full-text screening, and exclusion reasons"}, {"id": "db43a3e6-490d-490c-afac-da6c2ce5e2b0", "type": "concept", "title": "Reference managers, tagging, notes, PDFs, duplicate control, and shared libraries"}, {"id": "8f3f9473-7d12-4e56-96ee-ff2a2bf84757", "type": "concept", "title": "Citation ethics, primary versus secondary citation, retractions, corrections, and persistent identifiers"}]}, {"id": "db55aeb5-f09b-477b-aa21-7051e6990988", "type": "subtopic", "title": "Evidence mapping and gap analysis", "description": "Students synthesize study characteristics to distinguish a genuine research gap from a topic that is merely unfamiliar.", "children": [{"id": "1440e7db-6d32-49e2-af57-98cd4f47aba8", "type": "concept", "title": "Evidence tables, study matrices, concept maps, and scoping approaches"}, {"id": "1f5385f5-1441-477e-a763-6582da590cde", "type": "concept", "title": "Population, intervention/exposure, outcome, setting, time, and methodological gaps"}, {"id": "20e2f08f-b31e-46e6-8c17-bc0b7430cfa6", "type": "concept", "title": "Replication, extension, contradiction, implementation, and equity-oriented research opportunities"}]}]}, {"id": "0ad6c81d-b7f9-4b0f-8045-c88a723585df", "type": "topic", "title": "Study Designs and Causal Reasoning", "description": "Study design determines which comparisons are credible and what claims are justified. Students compare designs by the counterfactual they approximate, their vulnerabilities, and their fit to the question.", "children": [{"id": "9e21201e-486a-460f-b77f-46e18b811ca4", "type": "subtopic", "title": "Descriptive and analytic designs", "description": "Students distinguish studies that describe distributions from those that estimate associations, effects, or mechanisms.", "children": [{"id": "78a70c2d-1194-4090-b447-7365bee6c6c1", "type": "concept", "title": "Case reports/series, ecological studies, cross-sectional surveys, and surveillance"}, {"id": "dfd55efe-5842-4678-b3e5-bf605943820c", "type": "concept", "title": "Case-control, cohort, panel, natural experiment, and interrupted time-series designs"}, {"id": "317148b4-86d5-432d-8429-196af97b0005", "type": "concept", "title": "Prospective versus retrospective data; repeated measures and longitudinal follow-up"}]}, {"id": "4328df24-5f07-4def-899c-6b65b7cf40df", "type": "subtopic", "title": "Causal questions and target trials", "description": "The aim is to state the intervention, comparison, follow-up, outcome, and estimand that a causal claim requires.", "children": [{"id": "9be7fa2e-3c25-4765-bf8c-c42d6cf19bfd", "type": "concept", "title": "Potential outcomes, counterfactual comparisons, exchangeability, consistency, and positivity"}, {"id": "39860d1c-a801-43a6-96d7-4fc9be95a424", "type": "concept", "title": "Target-trial emulation, eligibility, treatment strategies, time zero, follow-up, and analysis"}, {"id": "5fec21e0-181f-4b25-aa85-193e0cc4512a", "type": "concept", "title": "Causal diagrams for design and adjustment; avoiding collider and overadjustment bias"}]}, {"id": "77a057ff-a4de-4885-a79e-8a5b7764eabd", "type": "subtopic", "title": "Design choice and triangulation", "description": "No single design answers every nutrition question; converging evidence can strengthen inference when biases differ.", "children": [{"id": "84f2329e-cf15-4c57-a86b-cd37d58f1840", "type": "concept", "title": "Internal validity, external validity, transportability, and generalizability"}, {"id": "176a0bad-cfbb-4f54-aaa2-cdcabe041e45", "type": "concept", "title": "Mechanistic, clinical, epidemiologic, qualitative, and policy evidence"}, {"id": "500e1ce2-5f98-48b5-9029-7c05d6ba0bbc", "type": "concept", "title": "Triangulation across methods, populations, measures, settings, and analytic assumptions"}]}]}, {"id": "7be44138-7041-4199-9923-ef3bd3cdbb69", "type": "topic", "title": "Experimental and Intervention Research", "description": "Experiments offer strong control over exposure assignment but still require careful intervention specification, adherence measurement, participant protection, and realistic interpretation.", "children": [{"id": "b18bdab2-95bb-469e-b25c-64af63f7c817", "type": "subtopic", "title": "Randomized trial architecture", "description": "Students learn how randomization protects comparability and how allocation and masking procedures prevent predictable bias.", "children": [{"id": "e546c7bd-7cce-4ea5-b5fb-a2a4492f837b", "type": "concept", "title": "Parallel, crossover, cluster, factorial, pragmatic, adaptive, and N-of-1 designs"}, {"id": "935a4a74-3183-471e-89a7-fcb5ea0a9eec", "type": "concept", "title": "Random sequence generation, allocation concealment, masking, control groups, and contamination"}, {"id": "4edc18fa-85df-41c9-96ab-e10540336073", "type": "concept", "title": "Superiority, equivalence, noninferiority, feasibility, pilot, and definitive trials"}]}, {"id": "00771f1f-36bc-4890-981c-80f7141c1a17", "type": "subtopic", "title": "Intervention development and fidelity", "description": "A trial cannot be interpreted if the intervention and comparison are poorly described or delivered inconsistently.", "children": [{"id": "721cc989-0d3e-437e-99ca-13dde661ec2d", "type": "concept", "title": "Theory of change, active ingredients, dose, tailoring, cointerventions, and usual care"}, {"id": "8eefb225-5fcc-4c5f-8ccd-92f163c24b10", "type": "concept", "title": "Fidelity, reach, adherence, retention, engagement, contamination, and treatment differentiation"}, {"id": "ab9415ae-9a86-401f-aa89-d990b8a75a03", "type": "concept", "title": "Process evaluation, implementation outcomes, adverse events, and unintended consequences"}]}, {"id": "103f2a73-16cf-46c6-9ca2-09e4e15dd9f1", "type": "subtopic", "title": "Trial analysis and interpretation", "description": "Students connect trial conduct to the analysis set and resist equating statistical significance with clinical importance.", "children": [{"id": "aad084f3-be99-4819-a22b-79ab1afc4981", "type": "concept", "title": "Intention-to-treat, per-protocol, as-treated, and sensitivity analyses"}, {"id": "ee81d0a6-2884-4d8b-8f4b-2123005dc07b", "type": "concept", "title": "Baseline balance, attrition, missing data, multiplicity, subgroup analysis, and stopping"}, {"id": "bd396663-8202-42e1-8af7-f94fc720c0e2", "type": "concept", "title": "Effect estimates, confidence intervals, minimal important differences, harms, and applicability"}]}]}, {"id": "6f6da274-dca3-4a11-a0f1-1e690763ec9c", "type": "topic", "title": "Observational and Nutritional Epidemiology", "description": "Nutrition evidence often relies on observational data because long-term randomized exposure is infeasible. Students learn to make disciplined inferences despite time-varying diets, correlated behaviors, and substantial measurement error.", "children": [{"id": "4e660bde-561a-4728-90af-488344159183", "type": "subtopic", "title": "Measures of frequency and association", "description": "Students interpret the quantities commonly reported in epidemiology and choose measures that match the design and question.", "children": [{"id": "cd0ce7df-0196-4127-9eea-d97a9c172e9e", "type": "concept", "title": "Prevalence, incidence risk, incidence rate, person-time, and survival"}, {"id": "fe65f743-ec06-4671-9554-cba5ff8260d9", "type": "concept", "title": "Risk difference, risk ratio, rate ratio, odds ratio, prevalence ratio, and hazard ratio"}, {"id": "9b4b0290-8ca8-436d-9828-48ba375519dc", "type": "concept", "title": "Absolute versus relative effects, standardization, attributable measures, and baseline risk"}]}, {"id": "022c201c-538c-4587-b7eb-fc17da077671", "type": "subtopic", "title": "Time, change, and life-course exposure", "description": "Diet and health vary over time, so temporal ordering and exposure windows are central to credible nutrition research.", "children": [{"id": "809b3d1d-4f81-4872-b3d9-611bc2b2642e", "type": "concept", "title": "Latency, induction, reverse causation, immortal time, and time-varying exposure"}, {"id": "d7dbc3dc-e7f6-441f-99b9-46e59402c72d", "type": "concept", "title": "Repeated dietary measures, cumulative averages, trajectories, change scores, and regression to the mean"}, {"id": "4eb8bb8f-e1a2-4587-8da4-9734138cba34", "type": "concept", "title": "Life-course models, critical periods, sensitive windows, and long-term follow-up"}]}, {"id": "24e4eb70-f723-4e5a-9433-2c9c3337ce4f", "type": "subtopic", "title": "Large datasets and complex surveys", "description": "Students learn why national survey estimates require documentation, weights, design variables, and population-specific interpretation.", "children": [{"id": "f9bfeb7a-8de5-4cfb-8c6d-85d48a7b1e7f", "type": "concept", "title": "NHANES structure, cycles, linkage, codebooks, inclusion rules, and analytic samples"}, {"id": "d77288af-e550-45c3-8f90-c2e0b7d98104", "type": "concept", "title": "Sampling weights, strata, clusters, variance estimation, domain analysis, and nonresponse"}, {"id": "c4266ea5-75d7-41d6-9488-d3070b7a5ec4", "type": "concept", "title": "Secondary-data limitations, harmonization, disclosure risk, and reproducible cohort construction"}]}]}, {"id": "70bbe6ac-3fb3-4e38-a530-6a6a43e2f484", "type": "topic", "title": "Dietary Assessment and Food-Exposure Measurement", "description": "Diet is multidimensional, variable, socially patterned, and difficult to recall. Students compare dietary instruments, match them to the target construct, and account for burden and systematic error.", "children": [{"id": "9aba22c5-17a5-4095-8123-d8fd7009e926", "type": "subtopic", "title": "Self-report dietary methods", "description": "Students select an instrument based on whether the study needs recent intake, usual intake, foods, nutrients, patterns, or eating context.", "children": [{"id": "0d6e49ef-822f-459a-817a-cb41dfa44a32", "type": "concept", "title": "Twenty-four-hour recalls, food records, food-frequency questionnaires, screeners, and diet histories"}, {"id": "b07348d6-a60b-4068-80a1-bb0acf8d9616", "type": "concept", "title": "Interviewer-administered, self-administered, technology-assisted, image-based, and ecological momentary methods"}, {"id": "1b34714e-b019-48bd-897a-3cbe09ecce83", "type": "concept", "title": "Portion estimation, probing, coding, food composition linkage, mixed dishes, recipes, and supplements"}]}, {"id": "e79ea8f6-5350-4989-99f1-04c64904100c", "type": "subtopic", "title": "Usual intake, energy adjustment, and patterns", "description": "The goal is to separate long-term intake from day-to-day variation and represent diet in analytically useful ways.", "children": [{"id": "c1e9a1a3-dd78-4094-a5e7-6b016169ea05", "type": "concept", "title": "Within-person and between-person variation; repeat recalls and usual-intake models"}, {"id": "9d2a95f8-66f3-4f62-bf65-cd1acf2564c1", "type": "concept", "title": "Energy-density, nutrient-density, residual, standard, and partition approaches"}, {"id": "fb7a4aa1-7159-40f5-8314-1eda15172313", "type": "concept", "title": "Diet quality indices, data-driven patterns, meal timing, substitution, and compositional interpretation"}]}, {"id": "6c13f8ab-a596-4b92-af4c-29f11a071d10", "type": "subtopic", "title": "Validity, calibration, and measurement error", "description": "Students learn that reliability does not guarantee validity and that error can distort estimates in predictable or unpredictable directions.", "children": [{"id": "9120344e-7eba-4152-9384-501059f2ffc8", "type": "concept", "title": "Random versus systematic error, differential error, reactivity, recall bias, and social desirability"}, {"id": "357f7364-6d41-4e94-886d-930574cc0b9b", "type": "concept", "title": "Reference instruments, biomarkers, recovery biomarkers, calibration studies, and method comparison"}, {"id": "1a4d331a-dfb4-4dd5-8de1-a468d0308994", "type": "concept", "title": "Attenuation, deattenuation, misclassification, reproducibility, sensitivity analyses, and validation limits"}]}]}, {"id": "7ff90318-be80-45f9-b1f4-9bb945893271", "type": "topic", "title": "Nutrition Status, Biomarkers, Anthropometry, and Measurement", "description": "Nutrition research integrates self-report with physical, biochemical, clinical, functional, and contextual measures. Students evaluate whether an instrument measures the intended construct consistently, validly, and equitably.", "children": [{"id": "be55018d-1de9-4ff7-b5de-fa28f7d8f1b2", "type": "subtopic", "title": "Measurement theory and instrument quality", "description": "Students distinguish constructs from operational definitions and examine how measurement quality affects every later result.", "children": [{"id": "fd663993-47e4-4f06-94cc-f4d0456d3c05", "type": "concept", "title": "Construct, criterion, convergent, discriminant, and content validity"}, {"id": "80e022e8-79d4-4995-af71-1a04b98cdbbb", "type": "concept", "title": "Reliability, repeatability, reproducibility, inter-rater agreement, responsiveness, and floor/ceiling effects"}, {"id": "5ebad543-f249-497d-bd3c-15819eab3a87", "type": "concept", "title": "Sensitivity, specificity, predictive values, likelihood ratios, cut points, and spectrum effects"}]}, {"id": "fb0ecacf-4672-4eea-ad39-909ea5eff840", "type": "subtopic", "title": "Anthropometry and body composition", "description": "Students appraise standardized measurement procedures and the assumptions behind common proxies.", "children": [{"id": "692b26e1-b346-406a-8455-f2a768f7d979", "type": "concept", "title": "Height, weight, BMI, circumferences, skinfolds, growth charts, and change over time"}, {"id": "12fb201d-2240-47dc-8b1f-975104c421a0", "type": "concept", "title": "Bioelectrical impedance, DXA, air displacement, imaging, and reference methods"}, {"id": "e2c1b1aa-da3d-47a4-a0c9-1b5a11ab5e02", "type": "concept", "title": "Calibration, positioning, technical error, biological variation, accessibility, privacy, and weight stigma"}]}, {"id": "6016a01a-9b9e-4d31-bcd6-da1032ca768e", "type": "subtopic", "title": "Biomarkers and clinical/functional measures", "description": "Biomarkers can improve exposure or outcome assessment, but preanalytic conditions and biological context determine meaning.", "children": [{"id": "38bb9fbd-70b9-4e88-af89-70b7dd10448b", "type": "concept", "title": "Exposure, status, effect, susceptibility, recovery, concentration, and predictive biomarkers"}, {"id": "e60ce77d-ffd2-4f98-b3cb-2fe8ecd8ec52", "type": "concept", "title": "Specimen timing, fasting, collection, processing, storage, batch effects, assay performance, and quality control"}, {"id": "4d7ad45e-504c-4393-aa64-dc5efa33e173", "type": "concept", "title": "Inflammation, hydration, homeostasis, medications, renal function, reference intervals, and interpretation"}]}]}, {"id": "aad9cc3f-b889-4459-8cae-cc7f336061a3", "type": "topic", "title": "Qualitative, Mixed-Methods, and Community-Engaged Research", "description": "Numbers alone cannot explain food meanings, intervention acceptability, implementation, or lived experience. Students learn rigorous qualitative inquiry and how community partnership can improve relevance and justice.", "children": [{"id": "3c5db86d-6e59-4668-82f4-c64225dd6938", "type": "subtopic", "title": "Qualitative design and data collection", "description": "Students align the qualitative tradition, sampling, data source, and researcher role with the question.", "children": [{"id": "30d5a123-ee98-4553-9a8b-63ba6f8290cf", "type": "concept", "title": "Phenomenology, grounded theory, ethnography, case study, narrative, and qualitative description"}, {"id": "fe8968fa-f8cf-48d8-a64f-1c74dae17973", "type": "concept", "title": "Purposeful/theoretical sampling, saturation or information power, interviews, focus groups, observation, and documents"}, {"id": "38a42a2a-5256-4f20-973a-2645753ffe56", "type": "concept", "title": "Interview guides, probing, field notes, reflexive journals, recording, transcription, and rapport"}]}, {"id": "b4fbf9b9-6e4d-453a-a177-224b40017220", "type": "subtopic", "title": "Qualitative analysis and trustworthiness", "description": "The point is to produce an interpretation grounded in data and transparent about the researcher's role.", "children": [{"id": "2af0383e-9cd0-4e97-9023-1719b8b5b046", "type": "concept", "title": "Familiarization, coding, codebooks, memoing, thematic/content/framework analysis, and deviant cases"}, {"id": "f9345e1b-5efd-4466-9576-368c1b52cf10", "type": "concept", "title": "Credibility, dependability, confirmability, transferability, reflexivity, and audit trails"}, {"id": "d61a069f-cb1a-4edd-ab89-55eeba521b3f", "type": "concept", "title": "Member reflection, peer debriefing, triangulation, team coding, and limits of mechanical agreement"}]}, {"id": "98c8f1d8-4bf4-4624-866f-98fac548e047", "type": "subtopic", "title": "Mixed methods and community partnership", "description": "Students learn when integration and shared governance add value rather than treating a qualitative component as decorative.", "children": [{"id": "2a74f8bc-b307-450d-87e7-4003833d6ca7", "type": "concept", "title": "Convergent, explanatory sequential, exploratory sequential, and embedded designs"}, {"id": "424ef333-b57a-4e9c-a2b6-7d3c5ef6795b", "type": "concept", "title": "Connecting, building, merging, joint displays, integration, and meta-inferences"}, {"id": "cdb6ec37-f38b-496d-814c-9df572ec523a", "type": "concept", "title": "Community-based participatory research, co-design, power sharing, compensation, data sovereignty, dissemination, and reciprocity"}]}]}, {"id": "524c4955-afe5-4b5b-9f63-62ffde481060", "type": "topic", "title": "Sampling, Recruitment, Power, and Representativeness", "description": "Who enters a study determines whose experience the findings can represent. Students treat recruitment and retention as scientific and ethical design problems, not only logistics.", "children": [{"id": "4e9409a3-ab4c-4113-af7e-7026025e48c1", "type": "subtopic", "title": "Sampling frames and strategies", "description": "Students compare probability and nonprobability approaches and trace how the source population becomes the analytic sample.", "children": [{"id": "78fc4191-89f8-4524-851d-2ff72922b4d2", "type": "concept", "title": "Target, source, eligible, recruited, enrolled, retained, and analyzed populations"}, {"id": "d86114e3-4442-41f3-8cda-1e3fbc0bfba4", "type": "concept", "title": "Simple, systematic, stratified, cluster, multistage, quota, convenience, purposive, and respondent-driven sampling"}, {"id": "bc1ac8c0-64ac-4913-bd29-ef0df4a474a2", "type": "concept", "title": "Coverage, selection, volunteer, referral, survivor, and nonresponse bias"}]}, {"id": "fc58dce5-6f86-4001-bc89-a09d04d66b59", "type": "subtopic", "title": "Sample size and precision", "description": "The aim is to justify a sample using the decision the study must support, not a ritual threshold.", "children": [{"id": "fa966185-73b9-4be8-88fb-c9fb30ea1dbf", "type": "concept", "title": "Effect size, variability, alpha, power, precision, confidence-interval width, and design effect"}, {"id": "975e30ec-3083-402c-ae22-f104ce0922e1", "type": "concept", "title": "One- and two-sided hypotheses, clustering, repeated measures, attrition, multiple outcomes, and feasibility"}, {"id": "6a4bffc1-e5db-4768-9975-98c0ce4c4a20", "type": "concept", "title": "Minimum detectable effect, clinical importance, pilot-study limits, and simulation-based planning"}]}, {"id": "57bb93f1-2cb6-4c8b-a6ed-99b031a1ef44", "type": "subtopic", "title": "Inclusive recruitment and retention", "description": "Students design equitable participation while avoiding coercion, tokenism, and exclusion through unnecessary criteria.", "children": [{"id": "14aeb989-880b-4ea1-98eb-70b73250ecbd", "type": "concept", "title": "Language, disability, transportation, digital access, caregiving, work schedules, trust, and historical context"}, {"id": "7f1374fa-0092-4fd8-a962-e3d74bed6949", "type": "concept", "title": "Accessible materials, community channels, consent support, compensation, burden reduction, and flexible follow-up"}, {"id": "3515e69d-f9e4-4ce4-9f8e-a7505386ff44", "type": "concept", "title": "Enrollment and attrition monitoring, subgroup precision, intersectionality, and transparent representativeness claims"}]}]}, {"id": "8f0a8efc-9018-47e8-be8f-fe887955c0a4", "type": "topic", "title": "Biostatistics, Modeling, and Data Visualization", "description": "Statistical methods summarize variation and estimate uncertainty; they do not rescue a weak design. Students learn to select, check, interpret, and communicate analyses appropriate to nutrition data.", "children": [{"id": "a7e94aca-0e5b-4c80-a5a9-b463413f4c3b", "type": "subtopic", "title": "Descriptive statistics and distributions", "description": "Students explore data before modeling and choose summaries that reflect scale, shape, and missingness.", "children": [{"id": "f42c949f-1981-4112-94b4-e0a069b75c1c", "type": "concept", "title": "Variable types, distributions, center, spread, quantiles, skewness, transformations, and outliers"}, {"id": "630a8030-7778-424e-afd2-a8bed6179a46", "type": "concept", "title": "Cross-tabulations, rates, age standardization, confidence intervals, and sampling uncertainty"}, {"id": "22eac16f-a905-4131-a88b-e308137b872a", "type": "concept", "title": "Histograms, boxplots, density plots, scatterplots, line plots, uncertainty displays, and honest axes"}]}, {"id": "37caa04c-9dff-49a3-b3bb-a50e656fbcc0", "type": "subtopic", "title": "Estimation, testing, and regression", "description": "The emphasis is on effect estimates and uncertainty, with hypothesis tests used as one component of inference.", "children": [{"id": "600b31c2-9e97-410e-a3c0-64c93ae29fc5", "type": "concept", "title": "Sampling distributions, standard errors, confidence intervals, p-values, Type I/II errors, and multiplicity"}, {"id": "8854241b-2755-48e7-a374-cda1433f1cb4", "type": "concept", "title": "t-tests, nonparametric tests, chi-square tests, correlation, ANOVA, and basic power"}, {"id": "c17f1a8e-bc79-4067-91ef-1d32258a8b2a", "type": "concept", "title": "Linear, logistic, Poisson/log-binomial, and survival models; coefficients, contrasts, predictions, and fit"}]}, {"id": "c813b953-da54-4165-b3bc-1e891dcc2886", "type": "subtopic", "title": "Model specification and diagnostics", "description": "Students learn to connect models to the estimand, data-generating process, and assumptions.", "children": [{"id": "b35206fb-7447-4cac-9655-7479c1af5054", "type": "concept", "title": "Functional form, interactions, nonlinear terms, splines, transformations, and centering"}, {"id": "3a69c129-9150-458d-957b-80c59fb36145", "type": "concept", "title": "Residuals, influence, collinearity, overdispersion, proportional hazards, calibration, and discrimination"}, {"id": "28aef2f0-c7ed-467f-888d-cfd127d656bb", "type": "concept", "title": "Missing-data mechanisms, complete-case analysis, multiple imputation concepts, sensitivity analysis, and robustness"}]}]}, {"id": "4bf31f46-54c0-48fa-8eb4-3269143f6fe6", "type": "topic", "title": "Bias, Confounding, Effect Modification, and Robustness", "description": "Critical appraisal requires tracing how estimates could depart from the truth. Students identify bias pathways, distinguish confounding from interaction, and design analyses that expose dependence on assumptions.", "children": [{"id": "a68df861-cca6-4362-a06b-61e2c3f7f03a", "type": "subtopic", "title": "Selection and information bias", "description": "Students examine when participation, follow-up, measurement, or data availability depends on exposure and outcome.", "children": [{"id": "81f3cf08-44c8-4e98-b5ef-7d1f6066266a", "type": "concept", "title": "Selection, nonresponse, loss-to-follow-up, healthy-user, referral, and collider bias"}, {"id": "db543431-f7bf-4664-ad4b-a9ddec4f3231", "type": "concept", "title": "Recall, interviewer, observer, detection, surveillance, and misclassification bias"}, {"id": "49077dea-6966-4191-b826-04878d18221d", "type": "concept", "title": "Blinding, standardization, validation, inverse-probability concepts, quantitative bias analysis, and negative controls"}]}, {"id": "1bc222ef-dd7b-45dc-9ac2-d56f8fa0951f", "type": "subtopic", "title": "Confounding and adjustment", "description": "The goal is to identify common causes using subject knowledge and design—not select covariates solely by statistical significance.", "children": [{"id": "9579929d-0fa3-4d59-a8b4-21fc85651229", "type": "concept", "title": "Confounder criteria, exchangeability, backdoor paths, and sufficient adjustment sets"}, {"id": "2647c025-a16e-40b0-aeee-724152fd983e", "type": "concept", "title": "Restriction, matching, stratification, standardization, regression, weighting, and propensity scores"}, {"id": "bb1acbe1-d21f-45e0-af6d-585c4fad76d9", "type": "concept", "title": "Residual/unmeasured confounding, overadjustment, mediator control, and time-varying confounding"}]}, {"id": "a2c13ee0-f9bd-4120-9085-738081ed6e14", "type": "subtopic", "title": "Effect modification and sensitivity", "description": "Average effects may conceal meaningful heterogeneity, while subgroup claims are especially vulnerable to chance and selective reporting.", "children": [{"id": "e8fcea7a-a661-40e2-9400-7ea2df3adb97", "type": "concept", "title": "Additive and multiplicative interaction, subgroup effects, biological and public-health interpretation"}, {"id": "b99862b5-093b-41ad-b813-86e5d4cb6c17", "type": "concept", "title": "Prespecification, interaction tests, sparse data, multiplicity, and shrinkage concepts"}, {"id": "f5c87860-30df-47ea-87b7-9649cc385c98", "type": "concept", "title": "Specification curves, E-values as one tool, tipping-point analyses, alternative definitions, and robustness checks"}]}]}, {"id": "bb2802b8-f334-4306-8588-c3ea4517b69d", "type": "topic", "title": "Data Management, Reproducibility, and Open Science", "description": "A credible result requires a traceable workflow from raw data to final figure. Students practice data stewardship, reproducible analysis, and responsible sharing while protecting participants.", "children": [{"id": "98403dde-082c-4ccc-86d1-f425ea8a3d79", "type": "subtopic", "title": "Data structure, quality, and documentation", "description": "Students build analysis-ready data without destroying provenance or silently changing meaning.", "children": [{"id": "aec3e3e7-53f8-4f43-a2ad-d17328348018", "type": "concept", "title": "Data dictionaries, metadata, codebooks, identifiers, tidy structure, relational data, and units"}, {"id": "c480cd4f-ba7d-4231-a72a-e0b7da24341f", "type": "concept", "title": "Range, logic, duplicate, date, missingness, consistency, and provenance checks"}, {"id": "99458d2d-b7b1-4cf0-915d-5f1f5256fc17", "type": "concept", "title": "Raw/derived/final data separation, cleaning scripts, audit trails, issue logs, and quality-control plans"}]}, {"id": "e9471e0a-76ef-4484-a1db-26cbe4a33bf2", "type": "subtopic", "title": "Reproducible analytic workflow", "description": "The goal is for another analyst—and the future student—to understand and rerun the work.", "children": [{"id": "e3d411e5-04f9-4cea-bdff-c58e31039b79", "type": "concept", "title": "Scripted import, cleaning, analysis, tables, figures, and reports"}, {"id": "dd216970-ca5c-4c6b-850c-91807387eba4", "type": "concept", "title": "Project structure, relative paths, environments, version control, commits, branches, and review"}, {"id": "4469f40b-29ed-489b-9e9c-f5bbfa0e7159", "type": "concept", "title": "Seeds, computational notebooks, literate programming, dependency capture, and reproducibility checks"}]}, {"id": "ac3679c0-b691-4990-ade0-238561cf2687", "type": "subtopic", "title": "Preregistration, sharing, and FAIR stewardship", "description": "Students learn how transparency can reduce undisclosed flexibility while recognizing legitimate privacy and community constraints.", "children": [{"id": "95f18b2a-7b2d-4044-a5e3-8a8a4642cc75", "type": "concept", "title": "Protocols, preregistration, registered reports, analysis plans, deviations, and exploratory labeling"}, {"id": "c7579428-b531-45f9-9b22-c97f1725ba78", "type": "concept", "title": "FAIR principles, repositories, licenses, persistent identifiers, metadata, and data-use agreements"}, {"id": "26c9d152-aadd-4de4-8340-3e801275179a", "type": "concept", "title": "NIH data-management plans, deidentification limits, controlled access, Indigenous/community data governance, code sharing, and reproducibility packages"}]}]}, {"id": "e6ea2759-6f7e-49cb-af06-173f0dd9e2e3", "type": "topic", "title": "Research Ethics, Integrity, and Human-Participant Protection", "description": "Ethics is integral to scientific validity. Students apply principles of respect, beneficence, and justice to recruitment, consent, risk, data, authorship, and public communication.", "children": [{"id": "465a0884-a5a7-485d-8ec8-6d4792ad1e09", "type": "subtopic", "title": "Human-participant protections", "description": "Students distinguish research from practice and understand the roles of investigators, institutions, and ethics review.", "children": [{"id": "3ca96852-1474-4f10-9df2-b14497d73df6", "type": "concept", "title": "Belmont principles, Common Rule concepts, IRB review, exemption, expedited review, and continuing responsibilities"}, {"id": "5bfc4e09-b4ae-4ef2-b3b5-15984df9108c", "type": "concept", "title": "Risk-benefit assessment, equitable selection, privacy, confidentiality, vulnerable circumstances, and additional protections"}, {"id": "c638e959-dff5-4d5b-9349-c1631686978c", "type": "concept", "title": "Adverse events, unanticipated problems, protocol deviations, complaints, and institutional reporting pathways"}]}, {"id": "b3672f25-ebdd-46d4-96c8-fc740208ecca", "type": "subtopic", "title": "Consent and participant-centered practice", "description": "Consent is an ongoing communication process, not a signature alone.", "children": [{"id": "922fdf16-7d27-4ea6-a79c-df6f3542446e", "type": "concept", "title": "Information, comprehension, voluntariness, capacity, assent, permission, and authorized representatives"}, {"id": "013c928a-57a0-4078-9a3b-060b9c0f0a99", "type": "concept", "title": "Plain language, language access, teach-back, remote consent, broad consent, reconsent, and withdrawal"}, {"id": "53d0954a-a214-4889-a1e8-028d339cca99", "type": "concept", "title": "Therapeutic misconception, undue influence, compensation, incidental findings, return of results, and biospecimens"}]}, {"id": "c9526bfb-6755-468d-b9ea-baec7c6fb259", "type": "subtopic", "title": "Research integrity and responsible conduct", "description": "Students recognize practices that distort the record or unfairly distribute credit and responsibility.", "children": [{"id": "effcdd6e-c1d6-4635-b0eb-4a12d89b3cc4", "type": "concept", "title": "Fabrication, falsification, plagiarism, questionable research practices, image manipulation, and selective reporting"}, {"id": "af589e3b-1688-4123-8c97-8265e1d919c5", "type": "concept", "title": "Authorship criteria, contributorship, conflicts of interest, peer review, mentoring, collaboration, and record retention"}, {"id": "3834ca91-2a8d-4854-924b-60318c1ecd94", "type": "concept", "title": "Corrections, retractions, whistleblowing channels, dual-use concerns, AI-assisted work disclosure, and accountability"}]}]}, {"id": "ee9e7785-2bf0-43fb-97c3-445ca2cb225a", "type": "topic", "title": "Critical Appraisal and Certainty of Evidence", "description": "Critical appraisal asks whether a result is valid, important, applicable, and complete. Students move beyond hierarchy-only thinking to evaluate design-specific risks and the totality of evidence.", "children": [{"id": "1fbb7c29-8ebb-43d1-a22e-f8a92e0cb725", "type": "subtopic", "title": "Appraising individual studies", "description": "Students use structured questions without letting a checklist replace judgment.", "children": [{"id": "aae3faeb-74b0-427a-8a48-8b92e81f3139", "type": "concept", "title": "Question relevance, protocol, design, recruitment, exposure/intervention, outcomes, analysis, results, and reporting"}, {"id": "a3d8fdca-c121-4ebe-8ccf-62cbe69ef06d", "type": "concept", "title": "Risk-of-bias domains for randomized, observational, diagnostic, qualitative, and prediction studies"}, {"id": "bee061ad-3f5d-4c37-a742-7486d452cdd4", "type": "concept", "title": "Magnitude, precision, clinical importance, harms, funding, conflicts, applicability, and missing evidence"}]}, {"id": "f18c174f-7ef3-49c5-9c88-764f846f5409", "type": "subtopic", "title": "Reading results and claims", "description": "Students translate tables and figures into defensible statements and detect common interpretive errors.", "children": [{"id": "d29929c4-a2e0-4de1-858c-7d7ed0a65e9d", "type": "concept", "title": "Estimate versus p-value; confidence intervals; adjusted versus unadjusted results"}, {"id": "66652870-0ddd-4f5e-90ac-2c33a84ab27e", "type": "concept", "title": "Correlation versus causation, odds versus risk, surrogate outcomes, composite outcomes, and regression-to-the-mean"}, {"id": "bca8d83b-d11c-462c-8dee-820462f0c513", "type": "concept", "title": "Spin, causal language, selective emphasis, subgroup overreach, abstract/full-text mismatch, and press-release inflation"}]}, {"id": "cfae336c-3184-479c-9411-6b37f631a14d", "type": "subtopic", "title": "Certainty across a body of evidence", "description": "The goal is to explain confidence in an effect estimate and what future evidence could change.", "children": [{"id": "9c27c1b3-e88e-4054-9f3b-8f738cf0362c", "type": "concept", "title": "Risk of bias, inconsistency, indirectness, imprecision, and publication bias"}, {"id": "65309c74-96fc-4b8f-b77b-8ab6d21d9ecd", "type": "concept", "title": "Large effects, dose-response, residual confounding, coherence, and applicability"}, {"id": "cbe4c5f7-7580-4c5c-9425-8514195f7113", "type": "concept", "title": "GRADE concepts, evidence-to-decision factors, values, resources, equity, acceptability, feasibility, and recommendation strength"}]}]}, {"id": "0c6d181e-9127-44c9-becf-c5e844f650d4", "type": "topic", "title": "Systematic Reviews and Meta-Analysis", "description": "Evidence synthesis is research with a protocol, reproducible methods, and its own risks of bias. Students learn the full review workflow and interpret pooled estimates cautiously.", "children": [{"id": "b05dd1d9-f0b9-4045-b340-305e8207c654", "type": "subtopic", "title": "Review question, protocol, and search", "description": "Students distinguish systematic reviews from narrative reviews and select the right synthesis type.", "children": [{"id": "1d414688-54f5-46b6-9ae5-176be348f5f7", "type": "concept", "title": "Intervention, etiology, prevalence, diagnostic, prognostic, qualitative, scoping, and umbrella reviews"}, {"id": "876fcb76-ae4d-4603-97ee-8c01cd7f1207", "type": "concept", "title": "Protocol registration, eligibility criteria, information sources, peer-reviewed searches, and updates"}, {"id": "ee562eb2-d27d-4934-b7a7-1d7f35431fea", "type": "concept", "title": "PRISMA flow, duplicate screening, conflict resolution, automation support, and human verification"}]}, {"id": "bcd54061-1bd0-4111-8f62-02c01481f80d", "type": "subtopic", "title": "Extraction and risk of bias", "description": "The point is to capture comparable study information and evaluate bias independently of whether results are favorable.", "children": [{"id": "f82902f4-cb2c-4a48-8748-16a583d5bda3", "type": "concept", "title": "Piloted extraction forms, duplicate extraction, outcome definitions, time points, and unit conversion"}, {"id": "4b57dff0-a269-463e-a9de-9f910cc54dda", "type": "concept", "title": "Study-level versus result-level risk of bias; domain judgments and supporting quotations"}, {"id": "cc825fbd-c607-42f6-8a7d-2c2b08ba06ac", "type": "concept", "title": "Multiple reports, overlapping cohorts, missing results, investigator contact, and data provenance"}]}, {"id": "e0f37946-5f79-43fe-9946-23c9aa8bd49a", "type": "subtopic", "title": "Synthesis and meta-analysis concepts", "description": "Students learn what a pooled estimate represents and when pooling would mislead.", "children": [{"id": "ff4842ef-317a-4208-b5d4-f47639366fb7", "type": "concept", "title": "Effect-size harmonization, fixed-effect and random-effects models, weighting, and confidence intervals"}, {"id": "e80d0f02-941b-4265-a715-6f658115224a", "type": "concept", "title": "Clinical/methodological/statistical heterogeneity, forest plots, prediction intervals, and I-squared limits"}, {"id": "94c10186-cd71-432c-ab36-8b1918a598b2", "type": "concept", "title": "Subgroups, meta-regression, small-study effects, funnel plots, sensitivity analyses, certainty, and narrative synthesis"}]}]}, {"id": "720b31ca-d5ce-4341-a1f1-e946e937f742", "type": "topic", "title": "Scientific Writing, Reporting, and Peer Review", "description": "Clear reporting allows readers to judge and reproduce research. Students write for scientific and public audiences, use design-specific guidelines, and revise through structured peer review.", "children": [{"id": "41199649-54d6-4b5f-bf55-5d18416a42e4", "type": "subtopic", "title": "Research manuscripts and reporting guidelines", "description": "Students match the manuscript structure and reporting checklist to the study design while preserving a coherent scientific argument.", "children": [{"id": "6922c4fb-c272-4d5d-b560-1d3236bd04a1", "type": "concept", "title": "Title, abstract, introduction, methods, results, discussion, tables, figures, supplements, and data/code statements"}, {"id": "53a4bb2c-13fb-40f3-a1fd-9c47b93d4c3e", "type": "concept", "title": "CONSORT, STROBE/STROBE-nut, PRISMA, SPIRIT, TREND, COREQ, and appropriate EQUATOR guidance"}, {"id": "5a368699-58eb-4e17-8fc2-6c84a39a90a1", "type": "concept", "title": "Methods sufficient for replication, denominator clarity, participant flow, protocol deviations, harms, limitations, and funding"}]}, {"id": "a78da03b-4264-43d4-9e6c-e4daf3f4aced", "type": "subtopic", "title": "Tables, figures, and results narration", "description": "The aim is to communicate estimates efficiently without duplicating or decorating data.", "children": [{"id": "5adb7e6c-29ab-43f7-9fc3-893699aab6a9", "type": "concept", "title": "Table shells, analysis populations, units, denominators, missing data, footnotes, and significant-digit discipline"}, {"id": "b92fcd16-561d-4218-b19a-02abeb081c19", "type": "concept", "title": "Figure purpose, chart selection, uncertainty, accessible color, direct labels, alt text, and data-ink restraint"}, {"id": "47100f17-6d6a-432a-88ee-b0c6f2e362d8", "type": "concept", "title": "Results-first sentences, neutral reporting, no causal overclaiming, and separation of results from interpretation"}]}, {"id": "6e10c03d-5983-403b-9b8e-3ce138a30011", "type": "subtopic", "title": "Peer review and revision", "description": "Students practice giving specific, prioritized feedback and responding with evidence rather than defensiveness.", "children": [{"id": "4d78986b-c53c-4a10-b8b3-b95035763056", "type": "concept", "title": "Major versus minor concerns, validity, clarity, transparency, reproducibility, and respectful tone"}, {"id": "f02490c9-3111-412a-9cdc-dd4664770d60", "type": "concept", "title": "Reviewer disagreement, editorial decisions, response letters, tracked revisions, and change logs"}, {"id": "f17ceb19-05d6-40b6-ae87-e08b67527ee9", "type": "concept", "title": "Publication ethics, predatory journals, preprints, open peer review, post-publication critique, and corrections"}]}]}, {"id": "f4ef9d61-2a28-46cf-aff3-c9390d24452b", "type": "topic", "title": "Research Proposal, Dissemination, and Evidence Translation", "description": "The capstone integrates the course into a feasible, ethical nutrition protocol and dissemination plan. Students learn that research has value only when its claims, uncertainties, and implications are communicated responsibly.", "children": [{"id": "c16a30df-94e9-4398-b17b-66468f2c0f2b", "type": "subtopic", "title": "Proposal architecture and project management", "description": "Students assemble a persuasive protocol in which every method is justified by the research question.", "children": [{"id": "6304c123-2e96-48c6-b304-c4707ba5399b", "type": "concept", "title": "Specific aims, significance, innovation, approach, conceptual model, and expected contribution"}, {"id": "4e01032b-8e4b-433a-a6c9-43afb2042789", "type": "concept", "title": "Study population, design, measures, sample size, analysis, ethics, data plan, limitations, timeline, team, and budget"}, {"id": "12af5238-abf3-4401-bcec-1432b4d1f41d", "type": "concept", "title": "Milestones, dependencies, risk register, feasibility criteria, protocol review, and revision"}]}, {"id": "9e1412f7-51b4-473d-b9a7-ceb763d8986b", "type": "subtopic", "title": "Knowledge translation and implementation", "description": "Students distinguish generating evidence from supporting its appropriate use in policy, practice, and communities.", "children": [{"id": "4b365e2e-00e6-45ac-9fed-f92e5b5a1dbc", "type": "concept", "title": "Audience and decision context, evidence briefs, guidelines, policy communication, and shared decisions"}, {"id": "d45503ff-16f2-42c9-93b0-969e46fbc3b3", "type": "concept", "title": "Reach, effectiveness, adoption, implementation, maintenance, fidelity, adaptation, acceptability, feasibility, and sustainability"}, {"id": "d6790e2a-7c3d-4378-85a0-a36c74c095d1", "type": "concept", "title": "Co-production, stakeholder review, equity impact, unintended consequences, and de-implementation"}]}, {"id": "930a7c5f-e3d7-439f-8734-0d59e143ef16", "type": "subtopic", "title": "Oral, visual, and public communication", "description": "The goal is accurate, accessible communication that neither hides uncertainty nor amplifies hype.", "children": [{"id": "66e10f08-18ab-415c-8b44-279733ba20bd", "type": "concept", "title": "Scientific talks, posters, lightning talks, conference abstracts, public summaries, media interviews, and social content"}, {"id": "81068828-e45c-4d5f-831f-5ba79250e7e4", "type": "concept", "title": "Message maps, audience needs, plain language, numeracy, risk framing, uncertainty, and correction of misinformation"}, {"id": "22cdc17a-48dc-48b6-a7a0-96e1151f34d3", "type": "concept", "title": "Open materials, participant/community return of results, authorship/contribution, disclosure, and evaluation of dissemination"}]}]}], "dbBacked": true}$nrmjson$::jsonb,
  true,
  false,
  'course',
  'public'
where not exists (
  select 1 from public.learning_paths where slug = 'nutrition-research-methods'
);

update public.learning_paths
set
  title = 'Nutrition Research Methods',
  goal = 'Nutrition Research Methods',
  summary = 'This advanced undergraduate course develops the ability to ask, design, appraise, analyze, reproduce, and communicate nutrition research. Students progress from a consequential research question to a feasible protocol, integrating literature searching, causal and conceptual models, experimental and observational designs, dietary and nutrition-status measurement, qualitative and mixed methods, sampling, biostatistics, bias analysis, research ethics, open science, critical appraisal, evidence synthesis, scientific reporting, and knowledge translation. Applied laboratories use public or simulated nutrition data and culminate in a preregistered-style research proposal, reproducible analytic product, and oral defense.',
  data = $nrmjson${"slug": "nutrition-research-methods", "title": "Nutrition Research Methods", "description": "This advanced undergraduate course develops the ability to ask, design, appraise, analyze, reproduce, and communicate nutrition research. Students progress from a consequential research question to a feasible protocol, integrating literature searching, causal and conceptual models, experimental and observational designs, dietary and nutrition-status measurement, qualitative and mixed methods, sampling, biostatistics, bias analysis, research ethics, open science, critical appraisal, evidence synthesis, scientific reporting, and knowledge translation. Applied laboratories use public or simulated nutrition data and culminate in a preregistered-style research proposal, reproducible analytic product, and oral defense.", "topics": [{"id": "a65a0f63-cf65-4662-9aaa-501f02a0a1e1", "type": "topic", "title": "Research Foundations, Questions, and Protocol Logic", "description": "This section turns broad nutrition interests into answerable, ethical studies. Students learn that a coherent protocol begins with a consequential question and maintains alignment among the population, exposure or intervention, comparison, outcomes, timing, design, and analysis.", "children": [{"id": "c40a7827-2e19-4482-b2e3-956580b950be", "type": "subtopic", "title": "From problem to research question", "description": "The point is to define a question precise enough to guide evidence searching, measurement, and design while remaining meaningful to nutrition practice or population health.", "children": [{"id": "cdaa0e78-b696-4137-9b20-6e090f626ecd", "type": "concept", "title": "Problem statements, knowledge gaps, significance, and stakeholder relevance"}, {"id": "71afe6b3-9c8d-418f-ad49-a4d3acb330ef", "type": "concept", "title": "PICO, PECO, PICOT, SPIDER, and question frameworks for quantitative and qualitative inquiry"}, {"id": "15518b02-4536-438d-a94c-5be5f1488dc1", "type": "concept", "title": "Primary and secondary questions; explanatory, descriptive, predictive, and evaluative aims"}]}, {"id": "ec69f1f9-814e-4b11-a909-013691a0d701", "type": "subtopic", "title": "Conceptual models and hypotheses", "description": "A conceptual model makes assumptions visible before variables are collected or models are fitted.", "children": [{"id": "0ed45cc9-02d7-4f52-97e8-bf58d63226c3", "type": "concept", "title": "Constructs, variables, mechanisms, causal pathways, and theory"}, {"id": "1a659b10-04af-4a5a-b288-05aab27981b4", "type": "concept", "title": "Directional hypotheses, null hypotheses, estimands, and falsifiability"}, {"id": "c118df01-6735-4d4b-afa2-fcfff034cb5a", "type": "concept", "title": "Logic models, causal diagrams, mediators, confounders, colliders, and effect modifiers"}]}, {"id": "b60c4a45-8862-4a53-958c-9a9320a6f7e6", "type": "subtopic", "title": "Protocol coherence and feasibility", "description": "Students learn to test whether a proposed study can actually answer its question with available time, participants, measures, expertise, and resources.", "children": [{"id": "e40a53f6-ab39-457c-ba86-bb65e2044930", "type": "concept", "title": "Alignment of aims, design, measures, sampling, analysis, and interpretation"}, {"id": "1951e1ff-d614-4abc-a0c7-c2fb9d798e32", "type": "concept", "title": "Feasibility, acceptability, burden, cost, timeline, staffing, and pilot work"}, {"id": "62e8bd7f-177b-4a78-bc25-58791cfd455b", "type": "concept", "title": "Protocol version control, deviations, amendments, decision logs, and stopping rules"}]}]}, {"id": "e123f90f-9bc3-4caf-967a-11a9bc0181f5", "type": "topic", "title": "Literature Searching and Evidence Landscapes", "description": "Research begins by locating what is known, how it was studied, and where uncertainty remains. Students build transparent searches and organize evidence without confusing search-engine visibility with scientific quality.", "children": [{"id": "8b6e3cb2-196b-4ef2-9e05-5b6682c8c08c", "type": "subtopic", "title": "Information sources and search strategy", "description": "Students learn to choose databases and construct reproducible searches for nutrition, biomedical, behavioral, and public-health questions.", "children": [{"id": "8d0ce285-f011-4f73-8e9a-1780285b5bd0", "type": "concept", "title": "PubMed/MEDLINE, Embase, CINAHL, PsycINFO, Cochrane Library, Scopus/Web of Science, and grey literature"}, {"id": "7be7fd41-c6d6-4c59-926f-9a9e8cb9e30b", "type": "concept", "title": "Controlled vocabulary, keywords, Boolean logic, proximity, truncation, filters, and citation chaining"}, {"id": "77529210-cef9-4331-a54b-f66a25844e0d", "type": "concept", "title": "Search dates, full search strings, deduplication, alerts, and librarian consultation"}]}, {"id": "4b2062be-fbb5-4dec-9ed2-9215628f2d2a", "type": "subtopic", "title": "Screening, organization, and citation management", "description": "The goal is an auditable path from search results to the evidence used in a proposal or review.", "children": [{"id": "4fe8b031-4e3a-43b5-978b-28b1f59850c5", "type": "concept", "title": "Eligibility criteria, title/abstract screening, full-text screening, and exclusion reasons"}, {"id": "db43a3e6-490d-490c-afac-da6c2ce5e2b0", "type": "concept", "title": "Reference managers, tagging, notes, PDFs, duplicate control, and shared libraries"}, {"id": "8f3f9473-7d12-4e56-96ee-ff2a2bf84757", "type": "concept", "title": "Citation ethics, primary versus secondary citation, retractions, corrections, and persistent identifiers"}]}, {"id": "db55aeb5-f09b-477b-aa21-7051e6990988", "type": "subtopic", "title": "Evidence mapping and gap analysis", "description": "Students synthesize study characteristics to distinguish a genuine research gap from a topic that is merely unfamiliar.", "children": [{"id": "1440e7db-6d32-49e2-af57-98cd4f47aba8", "type": "concept", "title": "Evidence tables, study matrices, concept maps, and scoping approaches"}, {"id": "1f5385f5-1441-477e-a763-6582da590cde", "type": "concept", "title": "Population, intervention/exposure, outcome, setting, time, and methodological gaps"}, {"id": "20e2f08f-b31e-46e6-8c17-bc0b7430cfa6", "type": "concept", "title": "Replication, extension, contradiction, implementation, and equity-oriented research opportunities"}]}]}, {"id": "0ad6c81d-b7f9-4b0f-8045-c88a723585df", "type": "topic", "title": "Study Designs and Causal Reasoning", "description": "Study design determines which comparisons are credible and what claims are justified. Students compare designs by the counterfactual they approximate, their vulnerabilities, and their fit to the question.", "children": [{"id": "9e21201e-486a-460f-b77f-46e18b811ca4", "type": "subtopic", "title": "Descriptive and analytic designs", "description": "Students distinguish studies that describe distributions from those that estimate associations, effects, or mechanisms.", "children": [{"id": "78a70c2d-1194-4090-b447-7365bee6c6c1", "type": "concept", "title": "Case reports/series, ecological studies, cross-sectional surveys, and surveillance"}, {"id": "dfd55efe-5842-4678-b3e5-bf605943820c", "type": "concept", "title": "Case-control, cohort, panel, natural experiment, and interrupted time-series designs"}, {"id": "317148b4-86d5-432d-8429-196af97b0005", "type": "concept", "title": "Prospective versus retrospective data; repeated measures and longitudinal follow-up"}]}, {"id": "4328df24-5f07-4def-899c-6b65b7cf40df", "type": "subtopic", "title": "Causal questions and target trials", "description": "The aim is to state the intervention, comparison, follow-up, outcome, and estimand that a causal claim requires.", "children": [{"id": "9be7fa2e-3c25-4765-bf8c-c42d6cf19bfd", "type": "concept", "title": "Potential outcomes, counterfactual comparisons, exchangeability, consistency, and positivity"}, {"id": "39860d1c-a801-43a6-96d7-4fc9be95a424", "type": "concept", "title": "Target-trial emulation, eligibility, treatment strategies, time zero, follow-up, and analysis"}, {"id": "5fec21e0-181f-4b25-aa85-193e0cc4512a", "type": "concept", "title": "Causal diagrams for design and adjustment; avoiding collider and overadjustment bias"}]}, {"id": "77a057ff-a4de-4885-a79e-8a5b7764eabd", "type": "subtopic", "title": "Design choice and triangulation", "description": "No single design answers every nutrition question; converging evidence can strengthen inference when biases differ.", "children": [{"id": "84f2329e-cf15-4c57-a86b-cd37d58f1840", "type": "concept", "title": "Internal validity, external validity, transportability, and generalizability"}, {"id": "176a0bad-cfbb-4f54-aaa2-cdcabe041e45", "type": "concept", "title": "Mechanistic, clinical, epidemiologic, qualitative, and policy evidence"}, {"id": "500e1ce2-5f98-48b5-9029-7c05d6ba0bbc", "type": "concept", "title": "Triangulation across methods, populations, measures, settings, and analytic assumptions"}]}]}, {"id": "7be44138-7041-4199-9923-ef3bd3cdbb69", "type": "topic", "title": "Experimental and Intervention Research", "description": "Experiments offer strong control over exposure assignment but still require careful intervention specification, adherence measurement, participant protection, and realistic interpretation.", "children": [{"id": "b18bdab2-95bb-469e-b25c-64af63f7c817", "type": "subtopic", "title": "Randomized trial architecture", "description": "Students learn how randomization protects comparability and how allocation and masking procedures prevent predictable bias.", "children": [{"id": "e546c7bd-7cce-4ea5-b5fb-a2a4492f837b", "type": "concept", "title": "Parallel, crossover, cluster, factorial, pragmatic, adaptive, and N-of-1 designs"}, {"id": "935a4a74-3183-471e-89a7-fcb5ea0a9eec", "type": "concept", "title": "Random sequence generation, allocation concealment, masking, control groups, and contamination"}, {"id": "4edc18fa-85df-41c9-96ab-e10540336073", "type": "concept", "title": "Superiority, equivalence, noninferiority, feasibility, pilot, and definitive trials"}]}, {"id": "00771f1f-36bc-4890-981c-80f7141c1a17", "type": "subtopic", "title": "Intervention development and fidelity", "description": "A trial cannot be interpreted if the intervention and comparison are poorly described or delivered inconsistently.", "children": [{"id": "721cc989-0d3e-437e-99ca-13dde661ec2d", "type": "concept", "title": "Theory of change, active ingredients, dose, tailoring, cointerventions, and usual care"}, {"id": "8eefb225-5fcc-4c5f-8ccd-92f163c24b10", "type": "concept", "title": "Fidelity, reach, adherence, retention, engagement, contamination, and treatment differentiation"}, {"id": "ab9415ae-9a86-401f-aa89-d990b8a75a03", "type": "concept", "title": "Process evaluation, implementation outcomes, adverse events, and unintended consequences"}]}, {"id": "103f2a73-16cf-46c6-9ca2-09e4e15dd9f1", "type": "subtopic", "title": "Trial analysis and interpretation", "description": "Students connect trial conduct to the analysis set and resist equating statistical significance with clinical importance.", "children": [{"id": "aad084f3-be99-4819-a22b-79ab1afc4981", "type": "concept", "title": "Intention-to-treat, per-protocol, as-treated, and sensitivity analyses"}, {"id": "ee81d0a6-2884-4d8b-8f4b-2123005dc07b", "type": "concept", "title": "Baseline balance, attrition, missing data, multiplicity, subgroup analysis, and stopping"}, {"id": "bd396663-8202-42e1-8af7-f94fc720c0e2", "type": "concept", "title": "Effect estimates, confidence intervals, minimal important differences, harms, and applicability"}]}]}, {"id": "6f6da274-dca3-4a11-a0f1-1e690763ec9c", "type": "topic", "title": "Observational and Nutritional Epidemiology", "description": "Nutrition evidence often relies on observational data because long-term randomized exposure is infeasible. Students learn to make disciplined inferences despite time-varying diets, correlated behaviors, and substantial measurement error.", "children": [{"id": "4e660bde-561a-4728-90af-488344159183", "type": "subtopic", "title": "Measures of frequency and association", "description": "Students interpret the quantities commonly reported in epidemiology and choose measures that match the design and question.", "children": [{"id": "cd0ce7df-0196-4127-9eea-d97a9c172e9e", "type": "concept", "title": "Prevalence, incidence risk, incidence rate, person-time, and survival"}, {"id": "fe65f743-ec06-4671-9554-cba5ff8260d9", "type": "concept", "title": "Risk difference, risk ratio, rate ratio, odds ratio, prevalence ratio, and hazard ratio"}, {"id": "9b4b0290-8ca8-436d-9828-48ba375519dc", "type": "concept", "title": "Absolute versus relative effects, standardization, attributable measures, and baseline risk"}]}, {"id": "022c201c-538c-4587-b7eb-fc17da077671", "type": "subtopic", "title": "Time, change, and life-course exposure", "description": "Diet and health vary over time, so temporal ordering and exposure windows are central to credible nutrition research.", "children": [{"id": "809b3d1d-4f81-4872-b3d9-611bc2b2642e", "type": "concept", "title": "Latency, induction, reverse causation, immortal time, and time-varying exposure"}, {"id": "d7dbc3dc-e7f6-441f-99b9-46e59402c72d", "type": "concept", "title": "Repeated dietary measures, cumulative averages, trajectories, change scores, and regression to the mean"}, {"id": "4eb8bb8f-e1a2-4587-8da4-9734138cba34", "type": "concept", "title": "Life-course models, critical periods, sensitive windows, and long-term follow-up"}]}, {"id": "24e4eb70-f723-4e5a-9433-2c9c3337ce4f", "type": "subtopic", "title": "Large datasets and complex surveys", "description": "Students learn why national survey estimates require documentation, weights, design variables, and population-specific interpretation.", "children": [{"id": "f9bfeb7a-8de5-4cfb-8c6d-85d48a7b1e7f", "type": "concept", "title": "NHANES structure, cycles, linkage, codebooks, inclusion rules, and analytic samples"}, {"id": "d77288af-e550-45c3-8f90-c2e0b7d98104", "type": "concept", "title": "Sampling weights, strata, clusters, variance estimation, domain analysis, and nonresponse"}, {"id": "c4266ea5-75d7-41d6-9488-d3070b7a5ec4", "type": "concept", "title": "Secondary-data limitations, harmonization, disclosure risk, and reproducible cohort construction"}]}]}, {"id": "70bbe6ac-3fb3-4e38-a530-6a6a43e2f484", "type": "topic", "title": "Dietary Assessment and Food-Exposure Measurement", "description": "Diet is multidimensional, variable, socially patterned, and difficult to recall. Students compare dietary instruments, match them to the target construct, and account for burden and systematic error.", "children": [{"id": "9aba22c5-17a5-4095-8123-d8fd7009e926", "type": "subtopic", "title": "Self-report dietary methods", "description": "Students select an instrument based on whether the study needs recent intake, usual intake, foods, nutrients, patterns, or eating context.", "children": [{"id": "0d6e49ef-822f-459a-817a-cb41dfa44a32", "type": "concept", "title": "Twenty-four-hour recalls, food records, food-frequency questionnaires, screeners, and diet histories"}, {"id": "b07348d6-a60b-4068-80a1-bb0acf8d9616", "type": "concept", "title": "Interviewer-administered, self-administered, technology-assisted, image-based, and ecological momentary methods"}, {"id": "1b34714e-b019-48bd-897a-3cbe09ecce83", "type": "concept", "title": "Portion estimation, probing, coding, food composition linkage, mixed dishes, recipes, and supplements"}]}, {"id": "e79ea8f6-5350-4989-99f1-04c64904100c", "type": "subtopic", "title": "Usual intake, energy adjustment, and patterns", "description": "The goal is to separate long-term intake from day-to-day variation and represent diet in analytically useful ways.", "children": [{"id": "c1e9a1a3-dd78-4094-a5e7-6b016169ea05", "type": "concept", "title": "Within-person and between-person variation; repeat recalls and usual-intake models"}, {"id": "9d2a95f8-66f3-4f62-bf65-cd1acf2564c1", "type": "concept", "title": "Energy-density, nutrient-density, residual, standard, and partition approaches"}, {"id": "fb7a4aa1-7159-40f5-8314-1eda15172313", "type": "concept", "title": "Diet quality indices, data-driven patterns, meal timing, substitution, and compositional interpretation"}]}, {"id": "6c13f8ab-a596-4b92-af4c-29f11a071d10", "type": "subtopic", "title": "Validity, calibration, and measurement error", "description": "Students learn that reliability does not guarantee validity and that error can distort estimates in predictable or unpredictable directions.", "children": [{"id": "9120344e-7eba-4152-9384-501059f2ffc8", "type": "concept", "title": "Random versus systematic error, differential error, reactivity, recall bias, and social desirability"}, {"id": "357f7364-6d41-4e94-886d-930574cc0b9b", "type": "concept", "title": "Reference instruments, biomarkers, recovery biomarkers, calibration studies, and method comparison"}, {"id": "1a4d331a-dfb4-4dd5-8de1-a468d0308994", "type": "concept", "title": "Attenuation, deattenuation, misclassification, reproducibility, sensitivity analyses, and validation limits"}]}]}, {"id": "7ff90318-be80-45f9-b1f4-9bb945893271", "type": "topic", "title": "Nutrition Status, Biomarkers, Anthropometry, and Measurement", "description": "Nutrition research integrates self-report with physical, biochemical, clinical, functional, and contextual measures. Students evaluate whether an instrument measures the intended construct consistently, validly, and equitably.", "children": [{"id": "be55018d-1de9-4ff7-b5de-fa28f7d8f1b2", "type": "subtopic", "title": "Measurement theory and instrument quality", "description": "Students distinguish constructs from operational definitions and examine how measurement quality affects every later result.", "children": [{"id": "fd663993-47e4-4f06-94cc-f4d0456d3c05", "type": "concept", "title": "Construct, criterion, convergent, discriminant, and content validity"}, {"id": "80e022e8-79d4-4995-af71-1a04b98cdbbb", "type": "concept", "title": "Reliability, repeatability, reproducibility, inter-rater agreement, responsiveness, and floor/ceiling effects"}, {"id": "5ebad543-f249-497d-bd3c-15819eab3a87", "type": "concept", "title": "Sensitivity, specificity, predictive values, likelihood ratios, cut points, and spectrum effects"}]}, {"id": "fb0ecacf-4672-4eea-ad39-909ea5eff840", "type": "subtopic", "title": "Anthropometry and body composition", "description": "Students appraise standardized measurement procedures and the assumptions behind common proxies.", "children": [{"id": "692b26e1-b346-406a-8455-f2a768f7d979", "type": "concept", "title": "Height, weight, BMI, circumferences, skinfolds, growth charts, and change over time"}, {"id": "12fb201d-2240-47dc-8b1f-975104c421a0", "type": "concept", "title": "Bioelectrical impedance, DXA, air displacement, imaging, and reference methods"}, {"id": "e2c1b1aa-da3d-47a4-a0c9-1b5a11ab5e02", "type": "concept", "title": "Calibration, positioning, technical error, biological variation, accessibility, privacy, and weight stigma"}]}, {"id": "6016a01a-9b9e-4d31-bcd6-da1032ca768e", "type": "subtopic", "title": "Biomarkers and clinical/functional measures", "description": "Biomarkers can improve exposure or outcome assessment, but preanalytic conditions and biological context determine meaning.", "children": [{"id": "38bb9fbd-70b9-4e88-af89-70b7dd10448b", "type": "concept", "title": "Exposure, status, effect, susceptibility, recovery, concentration, and predictive biomarkers"}, {"id": "e60ce77d-ffd2-4f98-b3cb-2fe8ecd8ec52", "type": "concept", "title": "Specimen timing, fasting, collection, processing, storage, batch effects, assay performance, and quality control"}, {"id": "4d7ad45e-504c-4393-aa64-dc5efa33e173", "type": "concept", "title": "Inflammation, hydration, homeostasis, medications, renal function, reference intervals, and interpretation"}]}]}, {"id": "aad9cc3f-b889-4459-8cae-cc7f336061a3", "type": "topic", "title": "Qualitative, Mixed-Methods, and Community-Engaged Research", "description": "Numbers alone cannot explain food meanings, intervention acceptability, implementation, or lived experience. Students learn rigorous qualitative inquiry and how community partnership can improve relevance and justice.", "children": [{"id": "3c5db86d-6e59-4668-82f4-c64225dd6938", "type": "subtopic", "title": "Qualitative design and data collection", "description": "Students align the qualitative tradition, sampling, data source, and researcher role with the question.", "children": [{"id": "30d5a123-ee98-4553-9a8b-63ba6f8290cf", "type": "concept", "title": "Phenomenology, grounded theory, ethnography, case study, narrative, and qualitative description"}, {"id": "fe8968fa-f8cf-48d8-a64f-1c74dae17973", "type": "concept", "title": "Purposeful/theoretical sampling, saturation or information power, interviews, focus groups, observation, and documents"}, {"id": "38a42a2a-5256-4f20-973a-2645753ffe56", "type": "concept", "title": "Interview guides, probing, field notes, reflexive journals, recording, transcription, and rapport"}]}, {"id": "b4fbf9b9-6e4d-453a-a177-224b40017220", "type": "subtopic", "title": "Qualitative analysis and trustworthiness", "description": "The point is to produce an interpretation grounded in data and transparent about the researcher's role.", "children": [{"id": "2af0383e-9cd0-4e97-9023-1719b8b5b046", "type": "concept", "title": "Familiarization, coding, codebooks, memoing, thematic/content/framework analysis, and deviant cases"}, {"id": "f9345e1b-5efd-4466-9576-368c1b52cf10", "type": "concept", "title": "Credibility, dependability, confirmability, transferability, reflexivity, and audit trails"}, {"id": "d61a069f-cb1a-4edd-ab89-55eeba521b3f", "type": "concept", "title": "Member reflection, peer debriefing, triangulation, team coding, and limits of mechanical agreement"}]}, {"id": "98c8f1d8-4bf4-4624-866f-98fac548e047", "type": "subtopic", "title": "Mixed methods and community partnership", "description": "Students learn when integration and shared governance add value rather than treating a qualitative component as decorative.", "children": [{"id": "2a74f8bc-b307-450d-87e7-4003833d6ca7", "type": "concept", "title": "Convergent, explanatory sequential, exploratory sequential, and embedded designs"}, {"id": "424ef333-b57a-4e9c-a2b6-7d3c5ef6795b", "type": "concept", "title": "Connecting, building, merging, joint displays, integration, and meta-inferences"}, {"id": "cdb6ec37-f38b-496d-814c-9df572ec523a", "type": "concept", "title": "Community-based participatory research, co-design, power sharing, compensation, data sovereignty, dissemination, and reciprocity"}]}]}, {"id": "524c4955-afe5-4b5b-9f63-62ffde481060", "type": "topic", "title": "Sampling, Recruitment, Power, and Representativeness", "description": "Who enters a study determines whose experience the findings can represent. Students treat recruitment and retention as scientific and ethical design problems, not only logistics.", "children": [{"id": "4e9409a3-ab4c-4113-af7e-7026025e48c1", "type": "subtopic", "title": "Sampling frames and strategies", "description": "Students compare probability and nonprobability approaches and trace how the source population becomes the analytic sample.", "children": [{"id": "78fc4191-89f8-4524-851d-2ff72922b4d2", "type": "concept", "title": "Target, source, eligible, recruited, enrolled, retained, and analyzed populations"}, {"id": "d86114e3-4442-41f3-8cda-1e3fbc0bfba4", "type": "concept", "title": "Simple, systematic, stratified, cluster, multistage, quota, convenience, purposive, and respondent-driven sampling"}, {"id": "bc1ac8c0-64ac-4913-bd29-ef0df4a474a2", "type": "concept", "title": "Coverage, selection, volunteer, referral, survivor, and nonresponse bias"}]}, {"id": "fc58dce5-6f86-4001-bc89-a09d04d66b59", "type": "subtopic", "title": "Sample size and precision", "description": "The aim is to justify a sample using the decision the study must support, not a ritual threshold.", "children": [{"id": "fa966185-73b9-4be8-88fb-c9fb30ea1dbf", "type": "concept", "title": "Effect size, variability, alpha, power, precision, confidence-interval width, and design effect"}, {"id": "975e30ec-3083-402c-ae22-f104ce0922e1", "type": "concept", "title": "One- and two-sided hypotheses, clustering, repeated measures, attrition, multiple outcomes, and feasibility"}, {"id": "6a4bffc1-e5db-4768-9975-98c0ce4c4a20", "type": "concept", "title": "Minimum detectable effect, clinical importance, pilot-study limits, and simulation-based planning"}]}, {"id": "57bb93f1-2cb6-4c8b-a6ed-99b031a1ef44", "type": "subtopic", "title": "Inclusive recruitment and retention", "description": "Students design equitable participation while avoiding coercion, tokenism, and exclusion through unnecessary criteria.", "children": [{"id": "14aeb989-880b-4ea1-98eb-70b73250ecbd", "type": "concept", "title": "Language, disability, transportation, digital access, caregiving, work schedules, trust, and historical context"}, {"id": "7f1374fa-0092-4fd8-a962-e3d74bed6949", "type": "concept", "title": "Accessible materials, community channels, consent support, compensation, burden reduction, and flexible follow-up"}, {"id": "3515e69d-f9e4-4ce4-9f8e-a7505386ff44", "type": "concept", "title": "Enrollment and attrition monitoring, subgroup precision, intersectionality, and transparent representativeness claims"}]}]}, {"id": "8f0a8efc-9018-47e8-be8f-fe887955c0a4", "type": "topic", "title": "Biostatistics, Modeling, and Data Visualization", "description": "Statistical methods summarize variation and estimate uncertainty; they do not rescue a weak design. Students learn to select, check, interpret, and communicate analyses appropriate to nutrition data.", "children": [{"id": "a7e94aca-0e5b-4c80-a5a9-b463413f4c3b", "type": "subtopic", "title": "Descriptive statistics and distributions", "description": "Students explore data before modeling and choose summaries that reflect scale, shape, and missingness.", "children": [{"id": "f42c949f-1981-4112-94b4-e0a069b75c1c", "type": "concept", "title": "Variable types, distributions, center, spread, quantiles, skewness, transformations, and outliers"}, {"id": "630a8030-7778-424e-afd2-a8bed6179a46", "type": "concept", "title": "Cross-tabulations, rates, age standardization, confidence intervals, and sampling uncertainty"}, {"id": "22eac16f-a905-4131-a88b-e308137b872a", "type": "concept", "title": "Histograms, boxplots, density plots, scatterplots, line plots, uncertainty displays, and honest axes"}]}, {"id": "37caa04c-9dff-49a3-b3bb-a50e656fbcc0", "type": "subtopic", "title": "Estimation, testing, and regression", "description": "The emphasis is on effect estimates and uncertainty, with hypothesis tests used as one component of inference.", "children": [{"id": "600b31c2-9e97-410e-a3c0-64c93ae29fc5", "type": "concept", "title": "Sampling distributions, standard errors, confidence intervals, p-values, Type I/II errors, and multiplicity"}, {"id": "8854241b-2755-48e7-a374-cda1433f1cb4", "type": "concept", "title": "t-tests, nonparametric tests, chi-square tests, correlation, ANOVA, and basic power"}, {"id": "c17f1a8e-bc79-4067-91ef-1d32258a8b2a", "type": "concept", "title": "Linear, logistic, Poisson/log-binomial, and survival models; coefficients, contrasts, predictions, and fit"}]}, {"id": "c813b953-da54-4165-b3bc-1e891dcc2886", "type": "subtopic", "title": "Model specification and diagnostics", "description": "Students learn to connect models to the estimand, data-generating process, and assumptions.", "children": [{"id": "b35206fb-7447-4cac-9655-7479c1af5054", "type": "concept", "title": "Functional form, interactions, nonlinear terms, splines, transformations, and centering"}, {"id": "3a69c129-9150-458d-957b-80c59fb36145", "type": "concept", "title": "Residuals, influence, collinearity, overdispersion, proportional hazards, calibration, and discrimination"}, {"id": "28aef2f0-c7ed-467f-888d-cfd127d656bb", "type": "concept", "title": "Missing-data mechanisms, complete-case analysis, multiple imputation concepts, sensitivity analysis, and robustness"}]}]}, {"id": "4bf31f46-54c0-48fa-8eb4-3269143f6fe6", "type": "topic", "title": "Bias, Confounding, Effect Modification, and Robustness", "description": "Critical appraisal requires tracing how estimates could depart from the truth. Students identify bias pathways, distinguish confounding from interaction, and design analyses that expose dependence on assumptions.", "children": [{"id": "a68df861-cca6-4362-a06b-61e2c3f7f03a", "type": "subtopic", "title": "Selection and information bias", "description": "Students examine when participation, follow-up, measurement, or data availability depends on exposure and outcome.", "children": [{"id": "81f3cf08-44c8-4e98-b5ef-7d1f6066266a", "type": "concept", "title": "Selection, nonresponse, loss-to-follow-up, healthy-user, referral, and collider bias"}, {"id": "db543431-f7bf-4664-ad4b-a9ddec4f3231", "type": "concept", "title": "Recall, interviewer, observer, detection, surveillance, and misclassification bias"}, {"id": "49077dea-6966-4191-b826-04878d18221d", "type": "concept", "title": "Blinding, standardization, validation, inverse-probability concepts, quantitative bias analysis, and negative controls"}]}, {"id": "1bc222ef-dd7b-45dc-9ac2-d56f8fa0951f", "type": "subtopic", "title": "Confounding and adjustment", "description": "The goal is to identify common causes using subject knowledge and design—not select covariates solely by statistical significance.", "children": [{"id": "9579929d-0fa3-4d59-a8b4-21fc85651229", "type": "concept", "title": "Confounder criteria, exchangeability, backdoor paths, and sufficient adjustment sets"}, {"id": "2647c025-a16e-40b0-aeee-724152fd983e", "type": "concept", "title": "Restriction, matching, stratification, standardization, regression, weighting, and propensity scores"}, {"id": "bb1acbe1-d21f-45e0-af6d-585c4fad76d9", "type": "concept", "title": "Residual/unmeasured confounding, overadjustment, mediator control, and time-varying confounding"}]}, {"id": "a2c13ee0-f9bd-4120-9085-738081ed6e14", "type": "subtopic", "title": "Effect modification and sensitivity", "description": "Average effects may conceal meaningful heterogeneity, while subgroup claims are especially vulnerable to chance and selective reporting.", "children": [{"id": "e8fcea7a-a661-40e2-9400-7ea2df3adb97", "type": "concept", "title": "Additive and multiplicative interaction, subgroup effects, biological and public-health interpretation"}, {"id": "b99862b5-093b-41ad-b813-86e5d4cb6c17", "type": "concept", "title": "Prespecification, interaction tests, sparse data, multiplicity, and shrinkage concepts"}, {"id": "f5c87860-30df-47ea-87b7-9649cc385c98", "type": "concept", "title": "Specification curves, E-values as one tool, tipping-point analyses, alternative definitions, and robustness checks"}]}]}, {"id": "bb2802b8-f334-4306-8588-c3ea4517b69d", "type": "topic", "title": "Data Management, Reproducibility, and Open Science", "description": "A credible result requires a traceable workflow from raw data to final figure. Students practice data stewardship, reproducible analysis, and responsible sharing while protecting participants.", "children": [{"id": "98403dde-082c-4ccc-86d1-f425ea8a3d79", "type": "subtopic", "title": "Data structure, quality, and documentation", "description": "Students build analysis-ready data without destroying provenance or silently changing meaning.", "children": [{"id": "aec3e3e7-53f8-4f43-a2ad-d17328348018", "type": "concept", "title": "Data dictionaries, metadata, codebooks, identifiers, tidy structure, relational data, and units"}, {"id": "c480cd4f-ba7d-4231-a72a-e0b7da24341f", "type": "concept", "title": "Range, logic, duplicate, date, missingness, consistency, and provenance checks"}, {"id": "99458d2d-b7b1-4cf0-915d-5f1f5256fc17", "type": "concept", "title": "Raw/derived/final data separation, cleaning scripts, audit trails, issue logs, and quality-control plans"}]}, {"id": "e9471e0a-76ef-4484-a1db-26cbe4a33bf2", "type": "subtopic", "title": "Reproducible analytic workflow", "description": "The goal is for another analyst—and the future student—to understand and rerun the work.", "children": [{"id": "e3d411e5-04f9-4cea-bdff-c58e31039b79", "type": "concept", "title": "Scripted import, cleaning, analysis, tables, figures, and reports"}, {"id": "dd216970-ca5c-4c6b-850c-91807387eba4", "type": "concept", "title": "Project structure, relative paths, environments, version control, commits, branches, and review"}, {"id": "4469f40b-29ed-489b-9e9c-f5bbfa0e7159", "type": "concept", "title": "Seeds, computational notebooks, literate programming, dependency capture, and reproducibility checks"}]}, {"id": "ac3679c0-b691-4990-ade0-238561cf2687", "type": "subtopic", "title": "Preregistration, sharing, and FAIR stewardship", "description": "Students learn how transparency can reduce undisclosed flexibility while recognizing legitimate privacy and community constraints.", "children": [{"id": "95f18b2a-7b2d-4044-a5e3-8a8a4642cc75", "type": "concept", "title": "Protocols, preregistration, registered reports, analysis plans, deviations, and exploratory labeling"}, {"id": "c7579428-b531-45f9-9b22-c97f1725ba78", "type": "concept", "title": "FAIR principles, repositories, licenses, persistent identifiers, metadata, and data-use agreements"}, {"id": "26c9d152-aadd-4de4-8340-3e801275179a", "type": "concept", "title": "NIH data-management plans, deidentification limits, controlled access, Indigenous/community data governance, code sharing, and reproducibility packages"}]}]}, {"id": "e6ea2759-6f7e-49cb-af06-173f0dd9e2e3", "type": "topic", "title": "Research Ethics, Integrity, and Human-Participant Protection", "description": "Ethics is integral to scientific validity. Students apply principles of respect, beneficence, and justice to recruitment, consent, risk, data, authorship, and public communication.", "children": [{"id": "465a0884-a5a7-485d-8ec8-6d4792ad1e09", "type": "subtopic", "title": "Human-participant protections", "description": "Students distinguish research from practice and understand the roles of investigators, institutions, and ethics review.", "children": [{"id": "3ca96852-1474-4f10-9df2-b14497d73df6", "type": "concept", "title": "Belmont principles, Common Rule concepts, IRB review, exemption, expedited review, and continuing responsibilities"}, {"id": "5bfc4e09-b4ae-4ef2-b3b5-15984df9108c", "type": "concept", "title": "Risk-benefit assessment, equitable selection, privacy, confidentiality, vulnerable circumstances, and additional protections"}, {"id": "c638e959-dff5-4d5b-9349-c1631686978c", "type": "concept", "title": "Adverse events, unanticipated problems, protocol deviations, complaints, and institutional reporting pathways"}]}, {"id": "b3672f25-ebdd-46d4-96c8-fc740208ecca", "type": "subtopic", "title": "Consent and participant-centered practice", "description": "Consent is an ongoing communication process, not a signature alone.", "children": [{"id": "922fdf16-7d27-4ea6-a79c-df6f3542446e", "type": "concept", "title": "Information, comprehension, voluntariness, capacity, assent, permission, and authorized representatives"}, {"id": "013c928a-57a0-4078-9a3b-060b9c0f0a99", "type": "concept", "title": "Plain language, language access, teach-back, remote consent, broad consent, reconsent, and withdrawal"}, {"id": "53d0954a-a214-4889-a1e8-028d339cca99", "type": "concept", "title": "Therapeutic misconception, undue influence, compensation, incidental findings, return of results, and biospecimens"}]}, {"id": "c9526bfb-6755-468d-b9ea-baec7c6fb259", "type": "subtopic", "title": "Research integrity and responsible conduct", "description": "Students recognize practices that distort the record or unfairly distribute credit and responsibility.", "children": [{"id": "effcdd6e-c1d6-4635-b0eb-4a12d89b3cc4", "type": "concept", "title": "Fabrication, falsification, plagiarism, questionable research practices, image manipulation, and selective reporting"}, {"id": "af589e3b-1688-4123-8c97-8265e1d919c5", "type": "concept", "title": "Authorship criteria, contributorship, conflicts of interest, peer review, mentoring, collaboration, and record retention"}, {"id": "3834ca91-2a8d-4854-924b-60318c1ecd94", "type": "concept", "title": "Corrections, retractions, whistleblowing channels, dual-use concerns, AI-assisted work disclosure, and accountability"}]}]}, {"id": "ee9e7785-2bf0-43fb-97c3-445ca2cb225a", "type": "topic", "title": "Critical Appraisal and Certainty of Evidence", "description": "Critical appraisal asks whether a result is valid, important, applicable, and complete. Students move beyond hierarchy-only thinking to evaluate design-specific risks and the totality of evidence.", "children": [{"id": "1fbb7c29-8ebb-43d1-a22e-f8a92e0cb725", "type": "subtopic", "title": "Appraising individual studies", "description": "Students use structured questions without letting a checklist replace judgment.", "children": [{"id": "aae3faeb-74b0-427a-8a48-8b92e81f3139", "type": "concept", "title": "Question relevance, protocol, design, recruitment, exposure/intervention, outcomes, analysis, results, and reporting"}, {"id": "a3d8fdca-c121-4ebe-8ccf-62cbe69ef06d", "type": "concept", "title": "Risk-of-bias domains for randomized, observational, diagnostic, qualitative, and prediction studies"}, {"id": "bee061ad-3f5d-4c37-a742-7486d452cdd4", "type": "concept", "title": "Magnitude, precision, clinical importance, harms, funding, conflicts, applicability, and missing evidence"}]}, {"id": "f18c174f-7ef3-49c5-9c88-764f846f5409", "type": "subtopic", "title": "Reading results and claims", "description": "Students translate tables and figures into defensible statements and detect common interpretive errors.", "children": [{"id": "d29929c4-a2e0-4de1-858c-7d7ed0a65e9d", "type": "concept", "title": "Estimate versus p-value; confidence intervals; adjusted versus unadjusted results"}, {"id": "66652870-0ddd-4f5e-90ac-2c33a84ab27e", "type": "concept", "title": "Correlation versus causation, odds versus risk, surrogate outcomes, composite outcomes, and regression-to-the-mean"}, {"id": "bca8d83b-d11c-462c-8dee-820462f0c513", "type": "concept", "title": "Spin, causal language, selective emphasis, subgroup overreach, abstract/full-text mismatch, and press-release inflation"}]}, {"id": "cfae336c-3184-479c-9411-6b37f631a14d", "type": "subtopic", "title": "Certainty across a body of evidence", "description": "The goal is to explain confidence in an effect estimate and what future evidence could change.", "children": [{"id": "9c27c1b3-e88e-4054-9f3b-8f738cf0362c", "type": "concept", "title": "Risk of bias, inconsistency, indirectness, imprecision, and publication bias"}, {"id": "65309c74-96fc-4b8f-b77b-8ab6d21d9ecd", "type": "concept", "title": "Large effects, dose-response, residual confounding, coherence, and applicability"}, {"id": "cbe4c5f7-7580-4c5c-9425-8514195f7113", "type": "concept", "title": "GRADE concepts, evidence-to-decision factors, values, resources, equity, acceptability, feasibility, and recommendation strength"}]}]}, {"id": "0c6d181e-9127-44c9-becf-c5e844f650d4", "type": "topic", "title": "Systematic Reviews and Meta-Analysis", "description": "Evidence synthesis is research with a protocol, reproducible methods, and its own risks of bias. Students learn the full review workflow and interpret pooled estimates cautiously.", "children": [{"id": "b05dd1d9-f0b9-4045-b340-305e8207c654", "type": "subtopic", "title": "Review question, protocol, and search", "description": "Students distinguish systematic reviews from narrative reviews and select the right synthesis type.", "children": [{"id": "1d414688-54f5-46b6-9ae5-176be348f5f7", "type": "concept", "title": "Intervention, etiology, prevalence, diagnostic, prognostic, qualitative, scoping, and umbrella reviews"}, {"id": "876fcb76-ae4d-4603-97ee-8c01cd7f1207", "type": "concept", "title": "Protocol registration, eligibility criteria, information sources, peer-reviewed searches, and updates"}, {"id": "ee562eb2-d27d-4934-b7a7-1d7f35431fea", "type": "concept", "title": "PRISMA flow, duplicate screening, conflict resolution, automation support, and human verification"}]}, {"id": "bcd54061-1bd0-4111-8f62-02c01481f80d", "type": "subtopic", "title": "Extraction and risk of bias", "description": "The point is to capture comparable study information and evaluate bias independently of whether results are favorable.", "children": [{"id": "f82902f4-cb2c-4a48-8748-16a583d5bda3", "type": "concept", "title": "Piloted extraction forms, duplicate extraction, outcome definitions, time points, and unit conversion"}, {"id": "4b57dff0-a269-463e-a9de-9f910cc54dda", "type": "concept", "title": "Study-level versus result-level risk of bias; domain judgments and supporting quotations"}, {"id": "cc825fbd-c607-42f6-8a7d-2c2b08ba06ac", "type": "concept", "title": "Multiple reports, overlapping cohorts, missing results, investigator contact, and data provenance"}]}, {"id": "e0f37946-5f79-43fe-9946-23c9aa8bd49a", "type": "subtopic", "title": "Synthesis and meta-analysis concepts", "description": "Students learn what a pooled estimate represents and when pooling would mislead.", "children": [{"id": "ff4842ef-317a-4208-b5d4-f47639366fb7", "type": "concept", "title": "Effect-size harmonization, fixed-effect and random-effects models, weighting, and confidence intervals"}, {"id": "e80d0f02-941b-4265-a715-6f658115224a", "type": "concept", "title": "Clinical/methodological/statistical heterogeneity, forest plots, prediction intervals, and I-squared limits"}, {"id": "94c10186-cd71-432c-ab36-8b1918a598b2", "type": "concept", "title": "Subgroups, meta-regression, small-study effects, funnel plots, sensitivity analyses, certainty, and narrative synthesis"}]}]}, {"id": "720b31ca-d5ce-4341-a1f1-e946e937f742", "type": "topic", "title": "Scientific Writing, Reporting, and Peer Review", "description": "Clear reporting allows readers to judge and reproduce research. Students write for scientific and public audiences, use design-specific guidelines, and revise through structured peer review.", "children": [{"id": "41199649-54d6-4b5f-bf55-5d18416a42e4", "type": "subtopic", "title": "Research manuscripts and reporting guidelines", "description": "Students match the manuscript structure and reporting checklist to the study design while preserving a coherent scientific argument.", "children": [{"id": "6922c4fb-c272-4d5d-b560-1d3236bd04a1", "type": "concept", "title": "Title, abstract, introduction, methods, results, discussion, tables, figures, supplements, and data/code statements"}, {"id": "53a4bb2c-13fb-40f3-a1fd-9c47b93d4c3e", "type": "concept", "title": "CONSORT, STROBE/STROBE-nut, PRISMA, SPIRIT, TREND, COREQ, and appropriate EQUATOR guidance"}, {"id": "5a368699-58eb-4e17-8fc2-6c84a39a90a1", "type": "concept", "title": "Methods sufficient for replication, denominator clarity, participant flow, protocol deviations, harms, limitations, and funding"}]}, {"id": "a78da03b-4264-43d4-9e6c-e4daf3f4aced", "type": "subtopic", "title": "Tables, figures, and results narration", "description": "The aim is to communicate estimates efficiently without duplicating or decorating data.", "children": [{"id": "5adb7e6c-29ab-43f7-9fc3-893699aab6a9", "type": "concept", "title": "Table shells, analysis populations, units, denominators, missing data, footnotes, and significant-digit discipline"}, {"id": "b92fcd16-561d-4218-b19a-02abeb081c19", "type": "concept", "title": "Figure purpose, chart selection, uncertainty, accessible color, direct labels, alt text, and data-ink restraint"}, {"id": "47100f17-6d6a-432a-88ee-b0c6f2e362d8", "type": "concept", "title": "Results-first sentences, neutral reporting, no causal overclaiming, and separation of results from interpretation"}]}, {"id": "6e10c03d-5983-403b-9b8e-3ce138a30011", "type": "subtopic", "title": "Peer review and revision", "description": "Students practice giving specific, prioritized feedback and responding with evidence rather than defensiveness.", "children": [{"id": "4d78986b-c53c-4a10-b8b3-b95035763056", "type": "concept", "title": "Major versus minor concerns, validity, clarity, transparency, reproducibility, and respectful tone"}, {"id": "f02490c9-3111-412a-9cdc-dd4664770d60", "type": "concept", "title": "Reviewer disagreement, editorial decisions, response letters, tracked revisions, and change logs"}, {"id": "f17ceb19-05d6-40b6-ae87-e08b67527ee9", "type": "concept", "title": "Publication ethics, predatory journals, preprints, open peer review, post-publication critique, and corrections"}]}]}, {"id": "f4ef9d61-2a28-46cf-aff3-c9390d24452b", "type": "topic", "title": "Research Proposal, Dissemination, and Evidence Translation", "description": "The capstone integrates the course into a feasible, ethical nutrition protocol and dissemination plan. Students learn that research has value only when its claims, uncertainties, and implications are communicated responsibly.", "children": [{"id": "c16a30df-94e9-4398-b17b-66468f2c0f2b", "type": "subtopic", "title": "Proposal architecture and project management", "description": "Students assemble a persuasive protocol in which every method is justified by the research question.", "children": [{"id": "6304c123-2e96-48c6-b304-c4707ba5399b", "type": "concept", "title": "Specific aims, significance, innovation, approach, conceptual model, and expected contribution"}, {"id": "4e01032b-8e4b-433a-a6c9-43afb2042789", "type": "concept", "title": "Study population, design, measures, sample size, analysis, ethics, data plan, limitations, timeline, team, and budget"}, {"id": "12af5238-abf3-4401-bcec-1432b4d1f41d", "type": "concept", "title": "Milestones, dependencies, risk register, feasibility criteria, protocol review, and revision"}]}, {"id": "9e1412f7-51b4-473d-b9a7-ceb763d8986b", "type": "subtopic", "title": "Knowledge translation and implementation", "description": "Students distinguish generating evidence from supporting its appropriate use in policy, practice, and communities.", "children": [{"id": "4b365e2e-00e6-45ac-9fed-f92e5b5a1dbc", "type": "concept", "title": "Audience and decision context, evidence briefs, guidelines, policy communication, and shared decisions"}, {"id": "d45503ff-16f2-42c9-93b0-969e46fbc3b3", "type": "concept", "title": "Reach, effectiveness, adoption, implementation, maintenance, fidelity, adaptation, acceptability, feasibility, and sustainability"}, {"id": "d6790e2a-7c3d-4378-85a0-a36c74c095d1", "type": "concept", "title": "Co-production, stakeholder review, equity impact, unintended consequences, and de-implementation"}]}, {"id": "930a7c5f-e3d7-439f-8734-0d59e143ef16", "type": "subtopic", "title": "Oral, visual, and public communication", "description": "The goal is accurate, accessible communication that neither hides uncertainty nor amplifies hype.", "children": [{"id": "66e10f08-18ab-415c-8b44-279733ba20bd", "type": "concept", "title": "Scientific talks, posters, lightning talks, conference abstracts, public summaries, media interviews, and social content"}, {"id": "81068828-e45c-4d5f-831f-5ba79250e7e4", "type": "concept", "title": "Message maps, audience needs, plain language, numeracy, risk framing, uncertainty, and correction of misinformation"}, {"id": "22cdc17a-48dc-48b6-a7a0-96e1151f34d3", "type": "concept", "title": "Open materials, participant/community return of results, authorship/contribution, disclosure, and evaluation of dissemination"}]}]}], "dbBacked": true}$nrmjson$::jsonb,
